272	     */
273	    public boolean isDeleted() {
274	        return this.deleted;
275	    }
276	
277	    public void setDeleted(boolean deleted) {
278	        this.deleted = deleted;
279	    }
280	
281	    /**
282	     * The owner's membership points, derived on read: they start at 0, add 2 when an email is
283	     * present, add 1 when {@link #namesakeCount} is 0, add 2 for a household of 3 or more
284	     * ({@link #householdMemberCount}), and add 3 for tenure over one fiscal year (elapsed fiscal
285	     * years from {@link #registrationDate} to today; see {@link #hasTenureBonus(LocalDate)}).
286	     */
287	    @Transient
288	    public Integer getMembershipPoints() {
289	        return membershipPoints(this.email, this.namesakeCount, this.householdMemberCount,
290	            this.registrationDate);
291	    }
292	
293	    /**
294	     * The owner's numeric membership level, derived on read from {@link #getMembershipPoints()}:
295	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more; then held down to the owner's
296	     * {@link #getMembershipLevelCap() membership level cap} when one has been assigned.
297	     */
298	    @Transient
299	    public Integer getMembershipLevel() {
300	        return capMembershipLevel(membershipLevel(getMembershipPoints()), this.membershipLevelCap);
301	    }
302	
303	    /** The membership points derived from the given factors: they start at 0, add 2 when
304	     *  {@code email} is present, add 1 when {@code namesakeCount} is 0, add 2 for a household of 3 or
305	     *  more ({@code householdMemberCount}), and add 3 for sufficient tenure (see
306	     *  {@link #hasTenureBonus(LocalDate)}). */
307	    private static int membershipPoints(String email, Integer namesakeCount,
308	            Integer householdMemberCount, LocalDate registrationDate) {
309	        int points = 0;
310	        if (email != null && !email.isBlank()) {
311	            points += 2;
312	        }
313	        if (namesakeCount != null && namesakeCount == 0) {
314	            points += 1;
315	        }
316	        if (householdMemberCount != null && householdMemberCount >= 3) {
317	            points += 2;
318	        }
319	        if (hasTenureBonus(registrationDate)) {
320	            points += 3;
321	        }
322	        return points;
323	    }
324	
325	    /** Whether the owner's tenure earns the membership tenure bonus: the elapsed fiscal years from
326	     *  {@code registrationDate} to today exceed one, i.e. the registration falls two or more fiscal
327	     *  years before the current one (fiscal years start 1 July). A null registration date earns no
328	     *  bonus. */
329	    private static boolean hasTenureBonus(LocalDate registrationDate) {
330	        return registrationDate != null
331	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
332	    }
333	
334	    /**
335	     * The fiscal year (starting 1 July) that contains {@code date}, identified by the calendar year
336	     * in which that fiscal year ends: a date in July-December belongs to the fiscal year ending the
337	     * following calendar year, and a date in January-June to the fiscal year ending that same year
338	     * (e.g. 2026-09-05 -> 2027, 2026-03-01 -> 2026).
339	     */
340	    public static int fiscalYear(LocalDate date) {
341	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
342	    }
343	
344	    /**
345	     * The two-digit fiscal-year segment for {@code date}: the last two digits of the fiscal year
346	     * (starting 1 July) that contains it, zero-padded (e.g. a date of 2026-09-05 falls in fiscal year
347	     * 2027 -> {@code "27"}). This is the bare numeric segment behind the {@code "FY"}-prefixed
348	     * {@link #getFiscalYear()} and is also the segment the controller stamps into an owner's
349	     * identifier; the fiscal-year rule itself lives in {@link #fiscalYear(LocalDate)} and is shared,
350	     * not duplicated.
351	     */
352	    public static String fiscalYearSegment(LocalDate date) {
353	        return String.format("%02d", fiscalYear(date) % 100);
354	    }
355	
356	    /**
357	     * The owner's fiscal year, derived on read from the (business-day-adjusted)
358	     * {@link #registrationDate} as {@code "FY<YY>"}, where YY is the two-digit
359	     * {@link #fiscalYearSegment(LocalDate) fiscal-year segment} of the registration date (e.g. a date
360	     * of 2026-09-05 yields {@code "FY27"}). Returns {@code null} when no registration date is
361	     * available.
362	     */
363	    @Transient
364	    public String getFiscalYear() {
365	        if (this.registrationDate == null) {
366	            return null;
367	        }
368	        return "FY" + fiscalYearSegment(this.registrationDate);
369	    }
370	
371	    /** The numeric membership level (1-4) mapped from membership points: 1 for 0-1 points, 2 for
372	     *  2-3, 3 for 4-5, and 4 for 6 or more. */
373	    private static int membershipLevel(int points) {
374	        if (points >= 6) {
375	            return 4;
376	        }
377	        if (points >= 4) {
378	            return 3;
379	        }
380	        if (points >= 2) {
381	            return 2;
382	        }
383	        return 1;
384	    }
385	
386	    /** The membership {@code level} held down to {@code cap}, i.e. the smaller of the two, when a cap
387	     *  is present; the level unchanged when {@code cap} is {@code null} and no ceiling applies. */
388	    private static int capMembershipLevel(int level, Integer cap) {
389	        return cap == null ? level : Math.min(level, cap);
390	    }
391	
392	    /**
393	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
394	     * present, otherwise {@code "PHONE"}.
395	     */
396	    @Transient
397	    public String getContactPreference() {
398	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
399	    }
400	
401	    /**
402	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
403	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
404	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
405	     * date to measure against) is available.
406	     */
407	    @Transient
408	    public String getAgeBand() {
409	        if (this.birthDate == null || this.registrationDate == null) {
410	            return null;
411	        }
412	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
413	        if (age < 18) {
414	            return "MINOR";
415	        }
416	        if (age < 65) {
417	            return "ADULT";
418	        }
419	        return "SENIOR";
420	    }
421	
422	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
423	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
424	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
425	        "NSW", new int[] {2000, 2099},
426	        "VIC", new int[] {3000, 3099},
427	        "QLD", new int[] {4000, 4099});
428	
429	    /**
430	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
431	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
432	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
433	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
434	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
435	     */
436	    @Transient
437	    public String getRegion() {
438	        String byPostcode = regionForPostcode(this.postcode);
439	        if (byPostcode != null) {
440	            return byPostcode;
441	        }
442	        if ("Sydney".equals(this.city)) {
443	            return "NSW";
444	        }
445	        if ("Melbourne".equals(this.city)) {
446	            return "VIC";
447	        }
448	        if ("Brisbane".equals(this.city)) {
449	            return "QLD";
450	        }
451	        return "UNKNOWN";
452	    }
453	
454	    /**
455	     * The region code stamped inside the owner's identifiers - the leading REGION segment of the
456	     * {@link #getMemberId() member id}. Defined here as the single source of the "region inside the
457	     * identifiers", deliberately kept separate from the user-facing {@link #getRegion() region} and
458	     * {@link #getLocality() locality} (which it currently equals) so the region baked into
459	     * identifiers can be evolved on its own without disturbing the plain region shown to users.
460	     * Today it is exactly the {@link #getRegion() region}.
461	     */
462	    @Transient
463	    public String getIdentityRegionCode() {
464	        return getRegion();
465	    }
466	
467	    /**
468	     * The owner's locality, derived on read as the plain {@link #getRegion() region}: the region
469	     * code derived from the postcode (falling back to the fixed city-to-region table
470	     * {@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}, else
471	     * {@code "UNKNOWN"}). It is a user-facing field, independent of the region
472	     * {@link #getIdentityRegionCode() stamped inside the identifiers}.
473	     */
474	    @Transient
475	    public String getLocality() {
476	        return getRegion();
477	    }
478	
479	    /** Region -> IANA timezone name, the fixed region-to-timezone table ({@code NSW ->
480	     *  Australia/Sydney}, {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
481	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
482	        "NSW", "Australia/Sydney",
483	        "VIC", "Australia/Melbourne",
484	        "QLD", "Australia/Brisbane");
485	
486	    /**
487	     * The owner's timezone, derived on read as the IANA name for the owner's
488	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table
489	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
490	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region carries no entry in
491	     * the table (e.g. {@code UNKNOWN}).
492	     */
493	    @Transient
494	    public String getTimezone() {
495	        return timezoneForRegion(getLocality());
496	    }
497	
498	    /**
499	     * The owner's segment, derived on read as {@code "<TIER>_<AREA>"}: one of {@code "PREMIUM_METRO"},
500	     * {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or {@code "STANDARD_REGIONAL"}. TIER is
501	     * {@code "PREMIUM"} when the {@link #getMembershipLevel() membership level} is 3 or more, otherwise
502	     * {@code "STANDARD"}. AREA is {@code "METRO"} when the {@link #getLocality() locality} is a known
503	     * region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise {@code "REGIONAL"}.
504	     */
505	    @Transient
506	    public String getOwnerSegment() {
507	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
508	        String area = REGION_POSTCODE_RANGES.containsKey(getLocality()) ? "METRO" : "REGIONAL";
509	        return tier + "_" + area;
510	    }
511	
512	    /** The IANA timezone name for {@code region} via the fixed region-to-timezone table, or
513	     *  {@code null} when the region carries no entry ({@code NSW -> Australia/Sydney},
514	     *  {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
515	    public static String timezoneForRegion(String region) {
516	        return REGION_TIMEZONES.get(region);
517	    }
518	
519	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
520	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
521	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
522	    public static int[] postcodeRangeForRegion(String region) {
523	        return REGION_POSTCODE_RANGES.get(region);
524	    }
525	
526	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
527	     *  absent, not a 4-digit value, or in no known range. */
528	    private static String regionForPostcode(String postcode) {
529	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
530	            return null;
531	        }
532	        int value = Integer.parseInt(postcode);
533	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
534	            int[] range = entry.getValue();
535	            if (value >= range[0] && value <= range[1]) {
536	                return entry.getKey();
537	            }
538	        }
539	        return null;
540	    }
541	
542	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
543	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
544	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
545	     *  {@code +1}), so a number matches at most one. */
546	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
547	        "+61", 9, "+1", 10);
548	
549	    /**
550	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
551	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
552	     * to the raw value when it is {@code null} or begins with no recognised country code.
553	     */
554	    @Transient
555	    public String getTelephoneDisplay() {
556	        if (this.telephone == null) {
557	            return null;
558	        }
559	        String countryCode = countryCodeOf(this.telephone);
560	        if (countryCode == null) {
561	            return this.telephone;
562	        }
563	        String national = this.telephone.substring(countryCode.length());
564	        StringBuilder grouped = new StringBuilder(countryCode);
565	        for (int i = 0; i < national.length(); i++) {
566	            if (i % 3 == 0) {
567	                grouped.append(' ');
568	            }
569	            grouped.append(national.charAt(i));
570	        }
571	        return grouped.toString();
572	    }
573	
574	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
575	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
576	    public static String countryCodeOf(String telephone) {
577	        if (telephone == null) {
578	            return null;
579	        }
580	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
581	            if (telephone.startsWith(countryCode)) {
582	                return countryCode;
583	            }
584	        }
585	        return null;
586	    }
587	
588	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
589	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
590	     *  {@code +1 => 10}). */
591	    public static Integer nationalNumberLength(String countryCode) {
592	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
593	    }
594	
595	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
596	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
597	     *  digit-free value yields {@code 0}. Used by the controller to compute the CHK segment stamped
598	     *  into an owner's member id, so the Luhn rule lives here once and is not duplicated. */
599	    public static int luhnCheckDigit(String value) {
600	        int sum = 0;
601	        boolean doubling = true;
602	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
603	            char c = value.charAt(i);
604	            if (c < '0' || c > '9') {
605	                continue;
606	            }
607	            int digit = c - '0';
608	            if (doubling) {
609	                digit *= 2;
610	                if (digit > 9) {
611	                    digit -= 9;
612	                }
613	            }
614	            sum += digit;
615	            doubling = !doubling;
616	        }
617	        return (10 - (sum % 10)) % 10;
618	    }
619	
620	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters; the
621	     *  upper-case rendering of {@link #sha256HexLower(String)}. */
622	    public static String sha256Hex(String input) {
623	        return sha256HexLower(input).toUpperCase(Locale.ROOT);
624	    }
625	
626	    /** The lower-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
627	    public static String sha256HexLower(String input) {
628	        try {
629	            byte[] digest = MessageDigest.getInstance("SHA-256")
630	                .digest(input.getBytes(StandardCharsets.UTF_8));
631	            StringBuilder sb = new StringBuilder(digest.length * 2);
632	            for (byte b : digest) {
633	                sb.append(String.format("%02x", b));
634	            }
635	            return sb.toString();
636	        }
637	        catch (NoSuchAlgorithmException e) {
638	            throw new IllegalStateException("SHA-256 not available", e);
639	        }
640	    }
641	
642	    protected Set<Pet> getPetsInternal() {
643	        if (this.pets == null) {
644	            this.pets = new HashSet<>();
645	        }
646	        return this.pets;
647	    }
648	
649	    protected void setPetsInternal(Set<Pet> pets) {
650	        this.pets = pets;
651	    }
652	
653	    public List<Pet> getPets() {
654	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
655	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
656	        return Collections.unmodifiableList(sortedPets);
657	    }
658	
659	    public void setPets(List<Pet> pets) {
660	        this.pets = new HashSet<>(pets);
661	    }
662	
663	    public void addPet(Pet pet) {
664	        getPetsInternal().add(pet);
665	        pet.setOwner(this);
666	    }
667	
668	    /**
669	     * Return the Pet with the given name, or null if none found for this Owner.
670	     *
671	     * @param name to test
672	     * @return true if pet name is already in use
673	     */
674	    public Pet getPet(String name) {
675	        return getPet(name, false);
676	    }
677	
678	    /**
679	     * Return the Pet with the given name, or null if none found for this Owner.
680	     *
681	     * @param name to test
682	     * @return true if pet name is already in use
683	     */
684	    public Pet getPet(String name, boolean ignoreNew) {
685	        name = name.toLowerCase();
686	        for (Pet pet : getPetsInternal()) {
687	            if (!ignoreNew || !pet.isNew()) {
688	                String compName = pet.getName();
689	                compName = compName.toLowerCase();
690	                if (compName.equals(name)) {
691	                    return pet;
692	                }
693	            }
694	        }
695	        return null;
696	    }
697	
698	    public Pet getPet(Integer petId) {
699	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
700	    }
701	
702	    @Override
703	    public String toString() {
704	        return new ToStringCreator(this)
705	
706	            .append("id", this.getId())
707	            .append("new", this.isNew())
708	            .append("lastName", this.getLastName())
709	            .append("firstName", this.getFirstName())
710	            .append("address", this.address)
711	            .append("city", this.city)
712	            .append("telephone", this.telephone)
713	            .toString();
714	    }
715	}
